    """Holiday dates in ``[start, end]`` inclusive."""
    return set(
        session.scalars(
            select(PublicHoliday.holiday_date).where(
                PublicHoliday.holiday_date >= start, PublicHoliday.holiday_date <= end
            )
        )
    )

